// The gates of the package transitions. Each gate is a pure function of the facts that its caller passes in.
// A gate runs no process and reads no file: the caller gives the exit status, the SHAs, and the branch facts.
// Plain data and pure functions only.

import type { ChangeState, PackageState } from "./states.ts";

/** The result of a gate: `ok`, or the reason that the transition is refused. */
export type GateResult =
  | { readonly ok: true }
  | { readonly ok: false; readonly reason: string };

/** A gate that passes. */
export const PASS: GateResult = { ok: true };

/** A gate that refuses with `reason`. */
export const refuse = (reason: string): GateResult => ({ ok: false, reason });

/** The facts of `implement`: the state it leaves, and the change, the dependencies, and the markers that the gate reads. */
export interface ImplementFacts {
  readonly from: PackageState;
  readonly change: ChangeState;
  /** True when each dependency of the package is `done`. */
  readonly depsDone: boolean;
  /** The number of `[NEEDS CLARIFICATION: ...]` markers that are open in the change. */
  readonly openMarkers: number;
  readonly note?: string;
  readonly decision?: "fix-code" | "revise-spec";
}

/**
 * The gate of `implement`.
 * From `planned`, the change must be `planned` or `implementing`, each dependency must be `done`, and no marker may be open.
 * From `blocked`, a note is needed.
 * From `doing`, after a failed `verify`, a `decision` is needed.
 */
export const gateImplement = (facts: ImplementFacts): GateResult => {
  if (facts.from === "blocked")
    return facts.note?.trim()
      ? PASS
      : refuse("`implement` from `blocked` needs a `--note`.");
  if (facts.from === "doing")
    return facts.decision !== undefined
      ? PASS
      : refuse("`implement` after a failed `verify` needs a `--decision`.");
  if (facts.change !== "planned" && facts.change !== "implementing")
    return refuse("The change must be `planned` or `implementing`.");
  if (!facts.depsDone) return refuse("Each dependency must be `done`.");
  if (facts.openMarkers > 0)
    return refuse("A `[NEEDS CLARIFICATION]` marker is still open.");
  return PASS;
};

/** The facts of `verify`: the command that ran, its exit status, the SHA it ran at, and the head of the branch. */
export interface VerifyFacts {
  readonly command: string;
  readonly exit: number;
  readonly sha: string;
  readonly head: string;
}

/**
 * The gate of the record of `verify`, for a pass and for a failure.
 * The command must be named, the exit status must be an integer, and the SHA must be the head of the branch.
 */
export const gateVerify = (facts: VerifyFacts): GateResult => {
  if (facts.command.trim() === "") return refuse("`verify` needs a command.");
  if (!Number.isInteger(facts.exit))
    return refuse("The exit status of `verify` must be an integer.");
  if (facts.sha === "" || facts.sha !== facts.head)
    return refuse("`verify` must run at the head of the branch.");
  return PASS;
};

/** The state after `verify`: `verified` when the exit status is `0`, and `doing` otherwise. */
export const verifyTarget = (exit: number): PackageState =>
  exit === 0 ? "verified" : "doing";

/** The facts of `review <package> approve`: the SHA of the last `verify` event, and the SHA of the approval. */
export interface ApproveFacts {
  readonly verifySha: string | undefined;
  readonly approveSha: string;
}

/** The gate of `approve`: the approval records the SHA of the last `verify` event. */
export const gateApprove = (facts: ApproveFacts): GateResult =>
  facts.verifySha !== undefined && facts.verifySha === facts.approveSha
    ? PASS
    : refuse("`approve` must record the SHA of the last `verify` event.");

/** The facts of `reject`: the findings and the decision. */
export interface RejectFacts {
  readonly findings: readonly string[];
  readonly decision?: "fix-code" | "revise-spec";
}

/** The gate of `reject`: one finding is needed, and the decision is `fix-code` or `revise-spec`. */
export const gateReject = (facts: RejectFacts): GateResult => {
  if (!facts.findings.some((f) => f.trim() !== ""))
    return refuse("`reject` needs a `--finding`.");
  if (facts.decision === undefined)
    return refuse(
      "`reject` needs a `--decision` of `fix-code` or `revise-spec`.",
    );
  return PASS;
};

/**
 * The facts of `merge`: the SHA of the approval, and either the head of the branch or the answer of the main checkout.
 * With a branch, the head of the branch must be the approved SHA.
 * With no branch, `mainContains` says whether `HEAD` of the main checkout contains the approved SHA.
 */
export interface MergeFacts {
  readonly approvedSha: string;
  readonly branchHead?: string;
  readonly mainContains: boolean;
}

/** The gate of `merge`. */
export const gateMerge = (facts: MergeFacts): GateResult => {
  if (facts.branchHead !== undefined)
    return facts.branchHead === facts.approvedSha
      ? PASS
      : refuse("The head of the branch must be the approved SHA.");
  return facts.mainContains
    ? PASS
    : refuse("`HEAD` of the main checkout must contain the approved SHA.");
};

/** The gate of `block --note` and of `drop --reason`: the text must not be empty. */
export const gateReason = (
  text: string | undefined,
  command: string,
): GateResult =>
  text !== undefined && text.trim() !== ""
    ? PASS
    : refuse(`\`${command}\` needs a note or a reason.`);
